window.OPUS_PAGES["029"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Carriage Return — A Typewriter for Letters</title>\n<meta name=\"description\" content=\"Type a letter on the Marlowe 44, a fictional mint-green portable typewriter: inked, imperfect characters, a moving carriage, a margin bell and a carriage-return lever, all drawn and synthesized in the browser.\">\n<meta name=\"theme-color\" content=\"#3a2212\">\n<style>\n:root{\n  --enamel:#9fc9b6;\n  --enamel-deep:#6f9d88;\n  --cream:#f3ead3;\n  --paper:#faf6ec;\n  --ink:#231f1c;\n  --red:#b3261e;\n  --chrome:#d7dcdf;\n  --wood-dark:#2b170b;\n  --lamp:#ffd79a;\n  --mono:\"Courier Prime\",\"American Typewriter\",\"Courier New\",\"Nimbus Mono PS\",Courier,monospace;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%}\nbody{background:#3a2212;color:var(--ink);font-family:var(--mono);overflow:hidden;-webkit-font-smoothing:antialiased}\n#scene{position:fixed;left:0;top:0;width:100%;height:100%;overflow:hidden;touch-action:manipulation}\n#desk,#motes{position:absolute;inset:0;width:100%;height:100%;display:block}\n#desk{z-index:0}\n#motes{z-index:8;pointer-events:none;mix-blend-mode:screen}\n\n/* ---------- machine layers (positioned by script) ---------- */\n.layer{position:absolute;left:0;top:0;display:block;overflow:visible}\n#shadow{z-index:1;border-radius:50%;background:radial-gradient(closest-side,rgba(12,6,2,.72),rgba(12,6,2,.35) 55%,rgba(12,6,2,0));pointer-events:none}\n#rear{z-index:2;transform-origin:50% 100%;transform:perspective(1100px) rotateX(24deg);\n  background:linear-gradient(180deg,#efe8d6 0%,#e7dfcb 60%,#cfc6b0 100%);\n  box-shadow:0 -1px 0 rgba(255,255,255,.5) inset,0 10px 30px rgba(0,0,0,.25);\n  transition:left 70ms cubic-bezier(.3,1.5,.55,1),height .2s ease-out,top .2s ease-out;pointer-events:none}\n#rear.returning{transition:left .46s cubic-bezier(.22,.9,.3,1.06),height .2s ease-out,top .2s ease-out}\n#rear.instant{transition:none}\n#rear::after{content:\"\";position:absolute;inset:0;background:\n  linear-gradient(100deg,rgba(255,252,240,.35),rgba(255,252,240,0) 45%,rgba(60,40,20,.1)),\n  repeating-linear-gradient(90deg,rgba(120,100,70,.035) 0 1px,transparent 1px 3px);mix-blend-mode:multiply}\n#rear::before{content:\"\";position:absolute;left:0;right:0;top:0;height:6px;background:linear-gradient(180deg,rgba(255,255,255,.6),rgba(255,255,255,0))}\n#carBack{z-index:3;pointer-events:none}\n#frontClip{z-index:4;overflow:hidden;pointer-events:none}\n#sheet{position:absolute;top:0;height:100%;pointer-events:auto;cursor:text}\n#paper{position:absolute;left:0;top:0;width:100%;display:block;box-shadow:0 -3px 10px rgba(40,25,10,.28),0 0 0 .5px rgba(90,70,40,.2)}\n.curl{position:absolute;left:-2px;right:-2px;pointer-events:none;background:linear-gradient(180deg,rgba(40,30,20,0) 0%,rgba(40,30,20,.12) 45%,rgba(20,14,8,.45) 100%)}\n#carFront{z-index:5;pointer-events:none}\n#carFront #lever{pointer-events:auto}\n#lever:focus-visible{outline:none}\n#lever:focus-visible .lv{filter:drop-shadow(0 0 3px #ffd79a) drop-shadow(0 0 2px #ffd79a)}\n#body{z-index:6}\n#guide{z-index:7;pointer-events:none}\n.carriage{transition:transform 70ms cubic-bezier(.3,1.5,.55,1)}\n.carriage.returning{transition:transform .46s cubic-bezier(.22,.9,.3,1.06)}\n.carriage.instant,.instant{transition:none!important}\n#paper{transition:transform .2s cubic-bezier(.3,1.3,.5,1)}\n\n/* keys */\n.kc{transition:transform 90ms ease-out;transform-box:fill-box;transform-origin:50% 50%}\n.key{cursor:pointer}\n.key.down .kc{transform:translateY(4px) scale(.965)}\n.key.down .cap{filter:brightness(.93)}\n.key:hover .cap{filter:brightness(1.03)}\n.key.on .cap{fill:url(#capLit)}\n#lever{cursor:pointer;transform-box:view-box;transform-origin:84px 44px;transition:transform .12s ease-out}\n#lever.pull{animation:pull .5s cubic-bezier(.3,.9,.4,1)}\n@keyframes pull{0%{transform:rotate(0)}30%{transform:rotate(26deg)}100%{transform:rotate(0)}}\n#lever:hover .lv{filter:brightness(1.08)}\n#typebar{opacity:0}\n#typebar.strike{animation:strike .11s ease-out}\n@keyframes strike{0%{opacity:0}25%{opacity:1}100%{opacity:0}}\n#spark{opacity:0;transform-box:fill-box;transform-origin:50% 50%}\n#spark.strike{animation:spark .16s ease-out}\n@keyframes spark{0%{opacity:0;transform:scale(.4)}30%{opacity:.8}100%{opacity:0;transform:scale(1.4)}}\n.ding{position:absolute;z-index:9;font-family:var(--mono);font-size:15px;color:#ffe6ae;letter-spacing:.2em;pointer-events:none;text-shadow:0 0 12px rgba(255,200,110,.8);animation:ding 1.3s ease-out forwards}\n@keyframes ding{0%{opacity:0;transform:translateY(6px) scale(.9)}15%{opacity:1}100%{opacity:0;transform:translateY(-34px) scale(1.05)}}\n\n/* sheet pull-out */\n.pulling{animation:pullout .75s cubic-bezier(.55,0,.8,.4) forwards}\n@keyframes pullout{to{transform:translateY(-120vh) rotate(-4deg)}}\n#rear.pulling{animation:pullrear .75s cubic-bezier(.55,0,.8,.4) forwards}\n@keyframes pullrear{to{transform:perspective(1100px) rotateX(24deg) translateY(-120vh)}}\n.feeding{animation:feedin .7s cubic-bezier(.2,.8,.3,1)}\n@keyframes feedin{from{transform:translateY(40px);opacity:0}to{transform:none;opacity:1}}\n\n/* ---------- header ---------- */\nheader.top{position:absolute;z-index:9;left:0;right:0;top:0;display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:22px 28px 0;pointer-events:none}\n.label{pointer-events:auto;position:relative;background:linear-gradient(180deg,#fbf6e8,#f1e8d2);padding:14px 22px 12px;transform:rotate(-1.4deg);box-shadow:0 12px 24px -10px rgba(0,0,0,.65),0 1px 0 rgba(255,255,255,.7) inset}\n.label::before,.label::after{content:\"\";position:absolute;top:-10px;width:62px;height:22px;background:rgba(236,224,190,.72);box-shadow:0 1px 2px rgba(0,0,0,.15);transform:rotate(-5deg)}\n.label::before{left:-14px}\n.label::after{right:-12px;transform:rotate(6deg)}\n.label h1{margin:0;font-size:clamp(20px,2.1vw,30px);letter-spacing:.14em;font-weight:700;color:#2a2421;text-transform:uppercase;text-shadow:.4px .3px 0 rgba(35,31,28,.35)}\n.label p{margin:4px 0 0;font-size:13px;color:var(--red);letter-spacing:.06em}\n.controls{pointer-events:auto;display:flex;flex-wrap:wrap;justify-content:flex-end;gap:10px;align-items:center;max-width:760px}\n.btn{\n  appearance:none;display:inline-flex;align-items:center;gap:8px;min-height:40px;padding:8px 16px 9px;cursor:pointer;\n  font:700 12.5px/1 var(--mono);letter-spacing:.08em;color:#2a2421;\n  background:radial-gradient(120% 140% at 50% 20%,#fffaf0 0%,#f2e7cc 62%,#dccfae 100%);\n  border:0;border-radius:999px;\n  box-shadow:0 0 0 2px #b9c0c4,0 0 0 3px #eef1f2,0 0 0 4px #7d868b,0 6px 14px -4px rgba(0,0,0,.7),inset 0 -3px 0 rgba(120,100,60,.22);\n  transition:transform .09s,box-shadow .09s,filter .2s;\n}\n.btn:hover{filter:brightness(1.04)}\n.btn:active,.btn.pressed{transform:translateY(2px);box-shadow:0 0 0 2px #b9c0c4,0 0 0 3px #eef1f2,0 0 0 4px #7d868b,0 3px 8px -4px rgba(0,0,0,.7),inset 0 -1px 0 rgba(120,100,60,.22)}\n.btn svg{width:15px;height:15px;flex:none}\n.btn:focus-visible,.seg button:focus-visible{outline:none}\n.btn:focus-visible,.seg button:focus-visible{box-shadow:0 0 0 2px #b9c0c4,0 0 0 3px #eef1f2,0 0 0 4px #7d868b,0 0 0 7px #ffd79a}\n.seg{display:inline-flex;align-items:center;gap:0;padding:4px;border-radius:999px;background:linear-gradient(180deg,#2b2320,#16110f);box-shadow:0 0 0 1px #7d868b,0 6px 14px -4px rgba(0,0,0,.7)}\n.seg .lbl{font-size:10.5px;letter-spacing:.2em;color:#d9cdb2;text-transform:uppercase;padding:0 10px 0 12px}\n.seg button{appearance:none;border:0;cursor:pointer;display:inline-flex;align-items:center;gap:7px;padding:7px 12px;border-radius:999px;background:transparent;color:#cfc3a8;font:700 12px/1 var(--mono);letter-spacing:.06em;transition:background .2s,color .2s}\n.seg button .dot{width:11px;height:11px;border-radius:50%;box-shadow:inset 0 -2px 2px rgba(0,0,0,.4)}\n.seg button[aria-pressed=\"true\"]{background:radial-gradient(120% 140% at 50% 20%,#fffaf0,#e8dcbd);color:#2a2421}\n\n/* ---------- desk props ---------- */\n.prop{position:absolute;z-index:1;pointer-events:none}\n.card{width:262px;padding:12px 20px 10px;background:\n  repeating-linear-gradient(180deg,transparent 0 21px,rgba(90,130,190,.3) 21px 22px) 0 12px/100% calc(100% - 12px) no-repeat,\n  linear-gradient(180deg,#fdf9ef,#f2ead6);\n  box-shadow:0 18px 30px -12px rgba(0,0,0,.7);transform:rotate(-4deg);font-size:12px;line-height:22px;color:#2c2622}\n.card::before{content:\"\";position:absolute;left:0;right:0;top:32px;height:1px;background:rgba(200,60,60,.6)}\n.card::after{content:\"\";position:absolute;top:0;bottom:0;left:13px;width:1px;background:rgba(200,60,60,.35)}\n.card h2{margin:0;font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--red);line-height:22px;white-space:nowrap}\n.card p{margin:0;white-space:nowrap}\n.card kbd{font-family:inherit;font-weight:700}\n.tag{width:230px;padding:14px 16px 14px 36px;background:linear-gradient(180deg,#f6ecd2,#e9dcbc);clip-path:polygon(22px 0,100% 0,100% 100%,22px 100%,0 50%);box-shadow:0 12px 24px -10px rgba(0,0,0,.6);transform:rotate(3deg);font-size:12px;line-height:1.75;color:#3a3029}\n.tag::before{content:\"\";position:absolute;left:12px;top:50%;width:9px;height:9px;margin-top:-4.5px;border-radius:50%;background:#3a2212;box-shadow:inset 0 1px 2px rgba(0,0,0,.6)}\n.tag b{color:var(--red);font-weight:700}\n.tag .row{display:flex;justify-content:space-between;gap:10px;border-bottom:1px dashed rgba(90,70,50,.3)}\n.tag .row:last-child{border-bottom:0}\n.pencil{width:210px;height:14px;transform:rotate(-24deg)}\n\n/* toast */\n.toast{position:absolute;z-index:10;left:50%;top:92px;transform:translate(-50%,-10px);opacity:0;pointer-events:none;background:#fbf6e8;color:#2a2421;padding:10px 18px;font-size:13px;letter-spacing:.04em;box-shadow:0 14px 30px -12px rgba(0,0,0,.75);transition:opacity .35s,transform .35s}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n.toast b{color:var(--red)}\n\n#ghost{position:absolute;z-index:0;left:50%;bottom:40%;width:2px;height:2px;opacity:0;border:0;padding:0;resize:none;font-size:16px;background:transparent;color:transparent;caret-color:transparent}\n.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n\n.kbtn{display:none}\n@media (max-width:1199px){.prop{display:none}}\n@media (max-width:700px){\n  .prop.card{display:block;width:232px;font-size:11px;line-height:20px;padding:10px 16px 8px;transform:rotate(-2.5deg);\n    background:repeating-linear-gradient(180deg,transparent 0 19px,rgba(90,130,190,.3) 19px 20px) 0 10px/100% calc(100% - 10px) no-repeat,linear-gradient(180deg,#fdf9ef,#f2ead6)}\n  .card::before{top:29px}\n  .card h2{line-height:20px;font-size:10.5px}\n  .card .m-hide{display:none}\n}\n@media (max-width:700px){\n  header.top{flex-direction:column;align-items:stretch;gap:12px;padding:14px 14px 0}\n  .label{align-self:flex-start;padding:10px 16px 9px}\n  .label h1{font-size:19px}\n  .label p{font-size:11.5px}\n  .controls{justify-content:flex-start;gap:8px;max-width:none}\n  .btn{min-height:36px;padding:7px 11px 8px;font-size:11px;gap:6px}\n  .seg .lbl{display:none}\n  .seg button{padding:6px 9px;font-size:11px}\n  .kbtn{display:inline-flex}\n  .toast{top:auto;bottom:46%}\n}\n@media (prefers-reduced-motion:reduce){\n  .carriage,.carriage.returning,#paper,#rear,.kc{transition:none}\n  #lever.pull,.pulling,#rear.pulling,.feeding,.ding{animation-duration:.01s}\n}\n</style>\n</head>\n<body>\n<main id=\"scene\" aria-label=\"Marlowe 44 typewriter on a desk\">\n  <canvas id=\"desk\" aria-hidden=\"true\"></canvas>\n\n  <aside class=\"prop card\" id=\"card\" aria-label=\"Operator's card\">\n    <h2>Marlowe 44 · operator</h2>\n    <p>Type away, or tap the keys.</p>\n    <p><kbd>Return</kbd> / lever: new line.</p>\n    <p><kbd>Backspace</kbd> steps back.</p>\n    <p class=\"m-hide\">(It never erases a thing.)</p>\n    <p><kbd>Tab</kbd> jumps five spaces.</p>\n    <p>Bell: six from the margin.</p>\n  </aside>\n  <svg class=\"prop pencil\" id=\"pencil\" viewBox=\"0 0 210 14\" aria-hidden=\"true\">\n    <defs><linearGradient id=\"pencilBody\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#f0c24a\"/><stop offset=\".5\" stop-color=\"#d9a11f\"/><stop offset=\"1\" stop-color=\"#a8770f\"/></linearGradient></defs>\n    <path d=\"M0 7L22 1.5V12.5Z\" fill=\"#e7c9a0\"/><path d=\"M0 7L7 5.2V8.8Z\" fill=\"#3b3430\"/>\n    <rect x=\"22\" y=\"1.5\" width=\"160\" height=\"11\" fill=\"url(#pencilBody)\"/>\n    <path d=\"M22 5.2H182M22 8.8H182\" stroke=\"rgba(120,80,10,.35)\" stroke-width=\".6\"/>\n    <rect x=\"182\" y=\"1\" width=\"12\" height=\"12\" fill=\"#c7cbcd\"/><path d=\"M185 1v12M189 1v12\" stroke=\"#8f979b\" stroke-width=\".8\"/>\n    <rect x=\"194\" y=\"1.5\" width=\"15\" height=\"11\" rx=\"3\" fill=\"#e58f95\"/>\n  </svg>\n  <aside class=\"prop tag\" id=\"tag\" aria-label=\"Letter status\">\n    <div class=\"row\"><span>Sheet</span><b id=\"stSheet\">No. 1</b></div>\n    <div class=\"row\"><span>Line</span><b id=\"stLine\">5 / 26</b></div>\n    <div class=\"row\"><span>Column</span><b id=\"stCol\">1 / 48</b></div>\n    <div class=\"row\"><span>Keystrokes</span><b id=\"stCount\">0</b></div>\n  </aside>\n\n  <div id=\"shadow\" class=\"layer\" aria-hidden=\"true\"></div>\n  <div id=\"rear\" class=\"layer carriage\" aria-hidden=\"true\"></div>\n\n  <!-- carriage, rear half: platen -->\n  <svg id=\"carBack\" class=\"layer carriage\" viewBox=\"0 0 1000 120\" aria-hidden=\"true\">\n    <defs>\n      <linearGradient id=\"platen\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n        <stop offset=\"0\" stop-color=\"#1a1716\"/><stop offset=\".22\" stop-color=\"#4a4441\"/><stop offset=\".34\" stop-color=\"#6d6562\"/>\n        <stop offset=\".46\" stop-color=\"#2e2a28\"/><stop offset=\".8\" stop-color=\"#141211\"/><stop offset=\"1\" stop-color=\"#0a0908\"/>\n      </linearGradient>\n      <linearGradient id=\"railG\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#f3f5f6\"/><stop offset=\".45\" stop-color=\"#9aa2a7\"/><stop offset=\".6\" stop-color=\"#e1e5e7\"/><stop offset=\"1\" stop-color=\"#6c747a\"/></linearGradient>\n      <linearGradient id=\"tableG\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#b6d8c7\"/><stop offset=\"1\" stop-color=\"#7fae98\"/></linearGradient>\n    </defs>\n    <path d=\"M150 34 Q500 14 850 34 L850 44 L150 44Z\" fill=\"url(#tableG)\" opacity=\".95\"/>\n    <rect x=\"96\" y=\"36\" width=\"808\" height=\"68\" rx=\"10\" fill=\"url(#platen)\"/>\n    <path d=\"M100 58H900\" stroke=\"rgba(255,255,255,.12)\" stroke-width=\"2\"/>\n    <rect x=\"70\" y=\"98\" width=\"860\" height=\"10\" rx=\"4\" fill=\"url(#railG)\"/>\n  </svg>\n\n  <div id=\"frontClip\" class=\"layer\" aria-hidden=\"false\">\n    <div id=\"sheet\" class=\"carriage\">\n      <canvas id=\"paper\" width=\"1200\" height=\"1552\" role=\"img\" aria-label=\"The letter on the typewriter paper\"></canvas>\n      <div class=\"curl\" id=\"curl\"></div>\n    </div>\n  </div>\n\n  <!-- carriage, front half: bail, scale, knobs, return lever -->\n  <svg id=\"carFront\" class=\"layer carriage\" viewBox=\"0 0 1000 120\" aria-label=\"Carriage\">\n    <defs>\n      <linearGradient id=\"chromeV\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fbfcfc\"/><stop offset=\".35\" stop-color=\"#b3babe\"/><stop offset=\".55\" stop-color=\"#eef1f2\"/><stop offset=\".8\" stop-color=\"#7e878c\"/><stop offset=\"1\" stop-color=\"#c9ced1\"/></linearGradient>\n      <linearGradient id=\"chromeH\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#7e878c\"/><stop offset=\".3\" stop-color=\"#f6f8f8\"/><stop offset=\".55\" stop-color=\"#aab2b6\"/><stop offset=\".8\" stop-color=\"#e9ecee\"/><stop offset=\"1\" stop-color=\"#6f777c\"/></linearGradient>\n      <linearGradient id=\"knobG\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3a3533\"/><stop offset=\".3\" stop-color=\"#6b6461\"/><stop offset=\".5\" stop-color=\"#2a2624\"/><stop offset=\"1\" stop-color=\"#0d0c0b\"/></linearGradient>\n    </defs>\n    <!-- paper bail -->\n    <!-- the rod sits in the gap between two typed lines, so it never hides the writing -->\n    <rect x=\"116\" y=\"61.6\" width=\"768\" height=\"3.2\" rx=\"1.6\" fill=\"url(#chromeV)\"/>\n    <rect id=\"rollL\" x=\"216\" y=\"58.6\" width=\"30\" height=\"9\" rx=\"4\" fill=\"#1b1817\"/>\n    <rect id=\"rollR\" x=\"754\" y=\"58.6\" width=\"30\" height=\"9\" rx=\"4\" fill=\"#1b1817\"/>\n    <path d=\"M216 60.2H246M754 60.2H784\" stroke=\"rgba(255,255,255,.18)\" stroke-width=\"1\"/>\n    <path d=\"M116 63.2 Q104 63.2 100 74M884 63.2 Q896 63.2 900 74\" stroke=\"url(#chromeV)\" stroke-width=\"3.4\" fill=\"none\"/>\n    <!-- margin scale -->\n    <rect x=\"130\" y=\"89\" width=\"740\" height=\"12\" rx=\"2\" fill=\"url(#chromeV)\"/>\n    <path d=\"M130 89.6H870\" stroke=\"rgba(255,255,255,.8)\" stroke-width=\".8\"/>\n    <g id=\"scaleTicks\"></g>\n    <!-- knobs -->\n    <g>\n      <rect x=\"44\" y=\"40\" width=\"46\" height=\"60\" rx=\"10\" fill=\"url(#knobG)\"/>\n      <path d=\"M50 44v52M56 43v54M62 43v54M68 43v54M74 43v54M80 43v54M86 44v52\" stroke=\"rgba(255,255,255,.1)\" stroke-width=\"1.5\"/>\n      <rect x=\"88\" y=\"56\" width=\"10\" height=\"28\" rx=\"3\" fill=\"url(#chromeH)\"/>\n    </g>\n    <g>\n      <rect x=\"904\" y=\"34\" width=\"62\" height=\"72\" rx=\"12\" fill=\"url(#knobG)\"/>\n      <path d=\"M912 38v64M920 37v66M928 37v66M936 37v66M944 37v66M952 37v66M960 38v64\" stroke=\"rgba(255,255,255,.1)\" stroke-width=\"1.6\"/>\n      <rect x=\"900\" y=\"54\" width=\"10\" height=\"32\" rx=\"3\" fill=\"url(#chromeH)\"/>\n    </g>\n    <!-- carriage return lever -->\n    <g id=\"lever\" role=\"button\" tabindex=\"0\" aria-label=\"Carriage return lever\">\n      <g class=\"lv\">\n        <path d=\"M84 42 C70 34 44 20 20 8\" stroke=\"url(#chromeV)\" stroke-width=\"9\" stroke-linecap=\"round\" fill=\"none\"/>\n        <path d=\"M84 42 C70 34 44 20 20 8\" stroke=\"rgba(255,255,255,.55)\" stroke-width=\"2\" stroke-linecap=\"round\" fill=\"none\" transform=\"translate(-1 -2)\"/>\n        <ellipse cx=\"18\" cy=\"7\" rx=\"14\" ry=\"10\" fill=\"url(#chromeV)\"/>\n        <ellipse cx=\"15\" cy=\"4\" rx=\"6\" ry=\"3\" fill=\"rgba(255,255,255,.7)\"/>\n        <circle cx=\"84\" cy=\"44\" r=\"9\" fill=\"url(#chromeV)\" stroke=\"#6f777c\" stroke-width=\"1\"/>\n      </g>\n      <rect x=\"0\" y=\"-8\" width=\"100\" height=\"62\" fill=\"transparent\"/>\n    </g>\n  </svg>\n\n  <!-- the body -->\n  <svg id=\"body\" class=\"layer\" viewBox=\"0 0 1000 350\" role=\"group\" aria-label=\"Marlowe 44 keyboard — tap keys to type\">\n    <defs>\n      <linearGradient id=\"enamel\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n        <stop offset=\"0\" stop-color=\"#c3e2d2\"/><stop offset=\".18\" stop-color=\"#a9d1be\"/><stop offset=\".55\" stop-color=\"#9fc9b6\"/><stop offset=\"1\" stop-color=\"#78a792\"/>\n      </linearGradient>\n      <linearGradient id=\"enamelSide\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#7aa893\"/><stop offset=\"1\" stop-color=\"#4f7766\"/></linearGradient>\n      <linearGradient id=\"deck\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#d3ecdf\"/><stop offset=\"1\" stop-color=\"#a3cdb9\"/></linearGradient>\n      <linearGradient id=\"well\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#5f8a77\"/><stop offset=\".25\" stop-color=\"#83b19c\"/><stop offset=\"1\" stop-color=\"#8dbba6\"/></linearGradient>\n      <radialGradient id=\"basket\" cx=\".5\" cy=\"0\" r=\"1\"><stop offset=\"0\" stop-color=\"#050404\"/><stop offset=\".7\" stop-color=\"#1c1917\"/><stop offset=\"1\" stop-color=\"#2d2825\"/></radialGradient>\n      <radialGradient id=\"cap\" cx=\".42\" cy=\".32\" r=\".75\"><stop offset=\"0\" stop-color=\"#fffcf4\"/><stop offset=\".6\" stop-color=\"#f3ead3\"/><stop offset=\"1\" stop-color=\"#d9caa5\"/></radialGradient>\n      <radialGradient id=\"capLit\" cx=\".42\" cy=\".32\" r=\".75\"><stop offset=\"0\" stop-color=\"#fff6dc\"/><stop offset=\".6\" stop-color=\"#f5d98f\"/><stop offset=\"1\" stop-color=\"#d2ad5c\"/></radialGradient>\n      <linearGradient id=\"rim\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffffff\"/><stop offset=\".4\" stop-color=\"#a7afb4\"/><stop offset=\".62\" stop-color=\"#e8ebed\"/><stop offset=\"1\" stop-color=\"#5f676c\"/></linearGradient>\n      <linearGradient id=\"chromeB\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fbfcfc\"/><stop offset=\".35\" stop-color=\"#b3babe\"/><stop offset=\".55\" stop-color=\"#eef1f2\"/><stop offset=\".8\" stop-color=\"#7e878c\"/><stop offset=\"1\" stop-color=\"#c9ced1\"/></linearGradient>\n      <radialGradient id=\"spoolG\" cx=\".5\" cy=\".5\" r=\".5\"><stop offset=\"0\" stop-color=\"#8b9297\"/><stop offset=\".25\" stop-color=\"#2b2725\"/><stop offset=\".3\" stop-color=\"#151211\"/><stop offset=\".92\" stop-color=\"#231f1d\"/><stop offset=\"1\" stop-color=\"#3b3532\"/></radialGradient>\n      <linearGradient id=\"spacebar\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fffaf0\"/><stop offset=\".6\" stop-color=\"#efe4c8\"/><stop offset=\"1\" stop-color=\"#cdbd96\"/></linearGradient>\n      <linearGradient id=\"gloss\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"rgba(255,255,255,.55)\"/><stop offset=\"1\" stop-color=\"rgba(255,255,255,0)\"/></linearGradient>\n    </defs>\n    <!-- side cheek (three-quarter view) -->\n    <path d=\"M900 16 L936 30 L992 292 Q994 306 978 312 L964 314 Z\" fill=\"url(#enamelSide)\"/>\n    <!-- main shell -->\n    <path d=\"M96 16 Q102 0 132 0 H868 Q898 0 904 16 L968 296 Q974 330 938 332 H62 Q26 330 32 296 Z\" fill=\"url(#enamel)\"/>\n    <path d=\"M110 6 H890\" stroke=\"rgba(255,255,255,.55)\" stroke-width=\"2\"/>\n    <!-- top deck with ribbon cups -->\n    <path d=\"M104 12 Q108 4 132 4 H868 Q892 4 896 12 L906 70 Q700 88 500 88 Q300 88 94 70 Z\" fill=\"url(#deck)\"/>\n    <path d=\"M94 70 Q300 88 500 88 Q700 88 906 70\" stroke=\"rgba(60,100,85,.45)\" stroke-width=\"2\" fill=\"none\"/>\n    <!-- basket opening + fanned typebars -->\n    <path d=\"M330 4 Q330 74 500 76 Q670 74 670 4 Z\" fill=\"url(#basket)\"/>\n    <g stroke=\"#9aa2a6\" stroke-width=\"2.2\" stroke-linecap=\"round\" opacity=\".9\">\n      <path d=\"M500 70L352 8M500 70L364 8M500 70L377 8M500 70L390 7M500 70L403 7M500 70L416 6M500 70L429 6M500 70L442 6M500 70L455 5M500 70L468 5M500 70L481 5M500 70L494 5\"/>\n      <path d=\"M500 70L648 8M500 70L636 8M500 70L623 8M500 70L610 7M500 70L597 7M500 70L584 6M500 70L571 6M500 70L558 6M500 70L545 5M500 70L532 5M500 70L519 5M500 70L506 5\"/>\n    </g>\n    <path d=\"M330 4 Q330 74 500 76 Q670 74 670 4\" fill=\"none\" stroke=\"url(#rim)\" stroke-width=\"4\"/>\n    <!-- ribbon cups -->\n    <g>\n      <ellipse cx=\"220\" cy=\"30\" rx=\"78\" ry=\"23\" fill=\"url(#chromeB)\"/>\n      <ellipse cx=\"220\" cy=\"29\" rx=\"66\" ry=\"17\" fill=\"url(#spoolG)\"/>\n      <ellipse cx=\"220\" cy=\"29\" rx=\"11\" ry=\"4\" fill=\"#c9ced1\"/>\n      <ellipse cx=\"780\" cy=\"30\" rx=\"78\" ry=\"23\" fill=\"url(#chromeB)\"/>\n      <ellipse cx=\"780\" cy=\"29\" rx=\"66\" ry=\"17\" fill=\"url(#spoolG)\"/>\n      <ellipse cx=\"780\" cy=\"29\" rx=\"11\" ry=\"4\" fill=\"#c9ced1\"/>\n      <path id=\"ribbonL\" d=\"M286 26 Q420 8 488 2\" stroke=\"#1d1a19\" stroke-width=\"7\" fill=\"none\"/>\n      <path id=\"ribbonR\" d=\"M714 26 Q580 8 512 2\" stroke=\"#1d1a19\" stroke-width=\"7\" fill=\"none\"/>\n      <path class=\"ribbonRed\" d=\"M286 29 Q420 11 488 5M714 29 Q580 11 512 5\" stroke=\"#9e2019\" stroke-width=\"3\" fill=\"none\"/>\n    </g>\n    <!-- badge -->\n    <g transform=\"translate(500 106)\">\n      <rect x=\"-86\" y=\"-16\" width=\"172\" height=\"30\" rx=\"15\" fill=\"url(#chromeB)\" stroke=\"#6f777c\" stroke-width=\"1\"/>\n      <rect x=\"-80\" y=\"-11\" width=\"160\" height=\"20\" rx=\"10\" fill=\"#1e3a33\"/>\n      <text x=\"-14\" y=\"5\" text-anchor=\"middle\" font-family=\"'Brush Script MT','Snell Roundhand','URW Chancery L','Z003',cursive\" font-style=\"italic\" font-size=\"20\" fill=\"#e9eef0\">Marlowe</text>\n      <circle cx=\"52\" cy=\"-1\" r=\"11\" fill=\"#b3261e\" stroke=\"#e9eef0\" stroke-width=\"1.2\"/>\n      <text x=\"52\" y=\"3.5\" text-anchor=\"middle\" font-family=\"'Courier New','Nimbus Mono PS',monospace\" font-weight=\"700\" font-size=\"11.5\" fill=\"#fff5e6\">44</text>\n    </g>\n    <!-- keyboard well -->\n    <path d=\"M86 128 Q88 120 104 120 H896 Q912 120 914 128 L944 300 Q946 314 930 314 H70 Q54 314 56 300 Z\" fill=\"url(#well)\" opacity=\".85\"/>\n    <g id=\"keys\"></g>\n    <!-- space bar -->\n    <g class=\"key\" id=\"spaceKey\" data-k=\" \" role=\"button\" aria-label=\"Space bar\">\n      <rect x=\"300\" y=\"302\" width=\"400\" height=\"9\" rx=\"3\" fill=\"#3d3a37\"/>\n      <g class=\"kc\">\n        <rect x=\"292\" y=\"284\" width=\"416\" height=\"24\" rx=\"12\" fill=\"url(#rim)\"/>\n        <rect x=\"298\" y=\"287\" width=\"404\" height=\"17\" rx=\"8.5\" fill=\"url(#spacebar)\" class=\"cap\"/>\n      </g>\n    </g>\n    <!-- chrome skirt + feet -->\n    <path d=\"M36 318 H964\" stroke=\"url(#chromeB)\" stroke-width=\"7\" stroke-linecap=\"round\"/>\n    <rect x=\"58\" y=\"326\" width=\"80\" height=\"16\" rx=\"7\" fill=\"#1a1512\"/>\n    <rect x=\"862\" y=\"326\" width=\"80\" height=\"16\" rx=\"7\" fill=\"#1a1512\"/>\n    <path d=\"M40 300 Q30 250 70 140\" stroke=\"url(#gloss)\" stroke-width=\"10\" fill=\"none\" opacity=\".35\"/>\n  </svg>\n\n  <!-- fixed parts at the printing point -->\n  <svg id=\"guide\" class=\"layer\" viewBox=\"0 0 1000 450\" aria-hidden=\"true\">\n    <defs>\n      <linearGradient id=\"barG\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#6b7378\"/><stop offset=\".5\" stop-color=\"#f3f5f6\"/><stop offset=\"1\" stop-color=\"#6b7378\"/></linearGradient>\n    </defs>\n    <line id=\"typebar\" x1=\"500\" y1=\"168\" x2=\"500\" y2=\"80\" stroke=\"url(#barG)\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n    <g id=\"guidePt\" transform=\"translate(500 0)\">\n      <!-- ribbon vibrator: black over red -->\n      <g id=\"vibrator\">\n        <rect x=\"-17\" y=\"81.5\" width=\"34\" height=\"3.8\" fill=\"#1d1a19\"/>\n        <rect x=\"-17\" y=\"85.3\" width=\"34\" height=\"3.8\" fill=\"#a4221b\"/>\n      </g>\n      <!-- type guide prongs -->\n      <path d=\"M-24 89.5 V79 Q-24 76 -21 76 M24 89.5 V79 Q24 76 21 76\" stroke=\"#e5e9eb\" stroke-width=\"2.4\" fill=\"none\" stroke-linecap=\"round\"/>\n      <!-- column pointer across the margin scale -->\n      <path d=\"M0 88.5 V101\" stroke=\"#b3261e\" stroke-width=\"1.6\"/>\n      <path d=\"M-3.4 86 H3.4 L0 90.2 Z\" fill=\"#b3261e\"/>\n      <circle id=\"spark\" cx=\"0\" cy=\"72\" r=\"9\" fill=\"rgba(255,240,200,.7)\"/>\n    </g>\n  </svg>\n\n  <canvas id=\"motes\" aria-hidden=\"true\"></canvas>\n\n  <header class=\"top\">\n    <div class=\"label\">\n      <h1>Carriage Return</h1>\n      <p>a typewriter for letters — the Marlowe 44</p>\n    </div>\n    <nav class=\"controls\" aria-label=\"Typewriter controls\">\n      <div class=\"seg\" role=\"group\" aria-label=\"Ribbon colour\">\n        <span class=\"lbl\">Ribbon</span>\n        <button type=\"button\" id=\"inkBlack\" aria-pressed=\"true\"><span class=\"dot\" style=\"background:#231f1c\"></span>Black</button>\n        <button type=\"button\" id=\"inkRed\" aria-pressed=\"false\"><span class=\"dot\" style=\"background:#b3261e\"></span>Red</button>\n      </div>\n      <button type=\"button\" class=\"btn\" id=\"btnSound\" aria-pressed=\"true\" aria-label=\"Sound on — press to mute\">\n        <svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M2 6h3l4-3v10L5 10H2z\" fill=\"currentColor\"/><path id=\"sndWaves\" d=\"M11 5.5a3.5 3.5 0 010 5M12.8 3.5a6 6 0 010 9\" stroke=\"currentColor\" stroke-width=\"1.4\" fill=\"none\"/></svg><span id=\"sndLbl\">Sound</span>\n      </button>\n      <button type=\"button\" class=\"btn kbtn\" id=\"btnKeyboard\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><rect x=\"1\" y=\"4\" width=\"14\" height=\"9\" rx=\"1.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/><path d=\"M4 7h1M7 7h1M10 7h1M4 10h8\" stroke=\"currentColor\" stroke-width=\"1.3\"/></svg>Keys</button>\n      <button type=\"button\" class=\"btn\" id=\"btnNew\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M3 1.5h7l3 3v10H3z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/><path d=\"M8 7v5M5.5 9.5h5\" stroke=\"currentColor\" stroke-width=\"1.3\"/></svg>New sheet</button>\n      <button type=\"button\" class=\"btn\" id=\"btnSave\"><svg viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M8 1.5v8.5M4.5 6.8L8 10.3l3.5-3.5M2 12v2.5h12V12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg>Save letter</button>\n    </nav>\n  </header>\n\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n  <textarea id=\"ghost\" aria-label=\"Type your letter\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\"></textarea>\n  <p class=\"sr-only\" id=\"announce\" aria-live=\"polite\"></p>\n</main>\n\n<script>\n(() => {\n'use strict';\nconst $=id=>document.getElementById(id);\nconst scene=$('scene'),deskC=$('desk'),motesC=$('motes'),paperC=$('paper');\nconst rear=$('rear'),carBack=$('carBack'),carFront=$('carFront'),bodyS=$('body'),guide=$('guide'),frontClip=$('frontClip'),sheet=$('sheet'),curl=$('curl'),shadow=$('shadow');\nconst reduceMQ=window.matchMedia('(prefers-reduced-motion: reduce)');\nlet reduced=reduceMQ.matches;\nconst MONO='\"Courier Prime\",\"American Typewriter\",\"Courier New\",\"Nimbus Mono PS\",Courier,monospace';\nconst STORE='marlowe44.letter.v1';\n\n/* ---------- paper geometry, in paper units (600 × 776, drawn at 2×) ---------- */\nconst PW=600,PH=776,ML=60,TM=76,CW=10,LH=26,COLS=48,LINES=26,FS=16.6;\nfunction mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}\n\n/* ---------- state ---------- */\nlet col=0,line=0,red=false,sheetNo=1,bellRung=false,shiftOn=false,lockOn=false;\nlet strokes=[]; // [ch,col,line,red,seed]\nlet muted=false;\n\n/* ---------- paper canvas ---------- */\nconst P=paperC.getContext('2d');\nconst glyph=document.createElement('canvas');glyph.width=glyph.height=72;const G=glyph.getContext('2d');\nconst weave=document.createElement('canvas');weave.width=weave.height=144;\n(function(){const w=weave.getContext('2d');const r=mulberry32(4);\n  for(let i=0;i<1700;i++){w.fillStyle='rgba(0,0,0,'+(0.25+r()*0.75)+')';const x=r()*144,y=r()*144;w.fillRect(x,y,1+r()*1.6,1+r()*1.2);}\n  w.globalAlpha=.35;w.strokeStyle='#000';w.lineWidth=.7;\n  for(let i=-144;i<288;i+=4){w.beginPath();w.moveTo(i,0);w.lineTo(i+144,144);w.stroke();}\n})();\nfunction paintPaper(seed){\n  const r=mulberry32(seed*7919+13);\n  P.setTransform(2,0,0,2,0,0);P.globalCompositeOperation='source-over';P.globalAlpha=1;\n  P.fillStyle='#faf6ec';P.fillRect(0,0,PW,PH);\n  // cloudy formation of the sheet\n  for(let i=0;i<60;i++){const x=r()*PW,y=r()*PH,rad=30+r()*90;const g=P.createRadialGradient(x,y,0,x,y,rad);const d=r()<.5;g.addColorStop(0,d?'rgba(214,200,170,0.07)':'rgba(255,255,250,0.1)');g.addColorStop(1,'rgba(255,255,255,0)');P.fillStyle=g;P.fillRect(x-rad,y-rad,rad*2,rad*2);}\n  // fibres\n  P.lineCap='round';\n  for(let i=0;i<900;i++){\n    const x=r()*PW,y=r()*PH,a=r()*Math.PI,l=2+r()*9;\n    P.strokeStyle=r()<.7?'rgba(160,140,105,'+(0.05+r()*0.08)+')':'rgba(120,135,160,'+(0.04+r()*0.05)+')';\n    P.lineWidth=.3+r()*.4;P.beginPath();P.moveTo(x,y);P.quadraticCurveTo(x+Math.cos(a+.6)*l*.5,y+Math.sin(a+.6)*l*.5,x+Math.cos(a)*l,y+Math.sin(a)*l);P.stroke();\n  }\n  for(let i=0;i<5200;i++){P.fillStyle=r()<.5?'rgba(120,100,70,0.06)':'rgba(255,255,255,0.18)';P.fillRect(r()*PW,r()*PH,.5+r()*.6,.5+r()*.6);}\n  // watermark (fictional paper maker)\n  P.save();P.translate(PW/2,PH*0.62);P.globalAlpha=.045;P.fillStyle='#7a6a4a';P.textAlign='center';\n  P.font='italic 30px Georgia,\"Times New Roman\",serif';P.fillText('Marlowe Bond',0,0);\n  P.font='11px '+MONO;P.fillText('25% COTTON FIBRE · No. 44',0,22);\n  P.strokeStyle='#7a6a4a';P.lineWidth=1;P.beginPath();P.ellipse(0,-8,122,40,0,0,Math.PI*2);P.stroke();\n  P.restore();\n  // edge darkening + deckle shading\n  const eg=P.createLinearGradient(0,0,PW,0);eg.addColorStop(0,'rgba(150,125,85,0.1)');eg.addColorStop(.04,'rgba(150,125,85,0)');eg.addColorStop(.96,'rgba(150,125,85,0)');eg.addColorStop(1,'rgba(150,125,85,0.1)');\n  P.fillStyle=eg;P.fillRect(0,0,PW,PH);\n  const tg=P.createLinearGradient(0,0,0,PH);tg.addColorStop(0,'rgba(150,125,85,0.1)');tg.addColorStop(.03,'rgba(150,125,85,0)');tg.addColorStop(.97,'rgba(150,125,85,0)');tg.addColorStop(1,'rgba(150,125,85,0.12)');\n  P.fillStyle=tg;P.fillRect(0,0,PW,PH);\n}\nconst inkRGB=[[35,31,28],[176,36,28]];\nfunction stampOne(s){\n  const [ch,c,l,isRed,seed]=s;\n  if(ch===' ')return;\n  const r=mulberry32(seed);\n  const rgb=inkRGB[isRed?1:0];\n  let dens=0.8+r()*0.2;\n  if(r()<0.07)dens*=0.58;                                  // a timid keystroke\n  dens*=0.9+0.1*Math.sin(c*0.31+l*1.7+seed%7);             // ribbon wear along the line\n  if(/[A-Z0-9#%&@$]/.test(ch))dens=Math.min(1,dens*1.06);   // heavier letters strike harder\n  const x=ML+c*CW+(r()-0.5)*0.9;\n  const y=TM+l*LH+(r()-0.5)*1.7;\n  // glyph on its own little plate (units ×2)\n  G.setTransform(1,0,0,1,0,0);G.globalCompositeOperation='source-over';G.globalAlpha=1;G.clearRect(0,0,72,72);\n  G.translate(36,48);G.rotate((r()-0.5)*0.045);\n  G.font='700 '+(FS*2)+'px '+MONO;G.textAlign='center';G.textBaseline='alphabetic';\n  G.shadowColor='rgba('+rgb[0]+','+rgb[1]+','+rgb[2]+',0.55)';G.shadowBlur=1.6;\n  G.fillStyle='rgb('+rgb[0]+','+rgb[1]+','+rgb[2]+')';\n  G.fillText(ch,0,0);\n  G.shadowBlur=0;G.setTransform(1,0,0,1,0,0);\n  // fabric ribbon: knock out specks of ink\n  G.globalCompositeOperation='destination-out';\n  G.globalAlpha=0.3+(1-dens)*0.9;G.drawImage(weave,-r()*72,-r()*72);\n  // uneven platen contact: one half of the letter prints lighter\n  if(r()<0.4){const top=r()<.5;const g=G.createLinearGradient(0,top?20:52,0,top?52:20);g.addColorStop(0,'rgba(0,0,0,'+(0.25+r()*0.35)+')');g.addColorStop(1,'rgba(0,0,0,0)');G.globalAlpha=1;G.fillStyle=g;G.fillRect(0,0,72,72);}\n  G.globalCompositeOperation='source-over';G.globalAlpha=1;\n  // onto the paper\n  P.setTransform(2,0,0,2,0,0);P.globalCompositeOperation='multiply';\n  P.globalAlpha=Math.min(1,dens);P.drawImage(glyph,x+CW/2-18,y-24,36,36);\n  if(r()<0.06){P.globalAlpha=dens*0.3;P.drawImage(glyph,x+CW/2-18+0.9,y-24+0.35,36,36);} // faint double strike\n  P.globalAlpha=1;P.globalCompositeOperation='source-over';\n}\nfunction redrawAll(){paintPaper(sheetNo);for(const s of strokes)stampOne(s);}\n\n/* ---------- layout ---------- */\nlet SW=0,SH=0,MW=0,U=1,MX=0,MY=0,S=1,mobile=false,K=1,X0=0,PRINTY=0;\nfunction layout(){\n  const vv=window.visualViewport;\n  SW=scene.clientWidth;SH=Math.round(vv&&mobile?Math.min(scene.clientHeight,vv.height):scene.clientHeight);\n  mobile=SW<700;\n  const hFit=(SH*(mobile?0.36:0.46))/0.45;\n  MW=Math.round(mobile?Math.min(SW-8,hFit):Math.min(920,SW*0.64,hFit));\n  U=MW/1000;\n  MX=Math.round((SW-MW)/2);\n  MY=Math.round(SH-450*U-(mobile?6:10));\n  const paperFrac=mobile?0.86:0.6;\n  S=paperFrac*MW/PW;\n  const travel=COLS*CW*S;\n  K=mobile?Math.max(0,Math.min(1,(SW-PW*S-16)/travel)):1;\n  X0=SW/2-(1-K)*travel/2;\n  PRINTY=MY+80*U;\n  const place=(el,x,y,w,h)=>{el.style.left=x+'px';el.style.top=y+'px';el.style.width=w+'px';if(h!==undefined)el.style.height=h+'px';};\n  place(carBack,MX,MY,MW,120*U);place(carFront,MX,MY,MW,120*U);\n  place(bodyS,MX,MY+100*U,MW,350*U);\n  place(guide,MX,MY,MW,450*U);\n  place(shadow,MX-MW*0.06,MY+300*U,MW*1.12,210*U);\n  frontClip.style.left='0px';frontClip.style.top='0px';frontClip.style.width=SW+'px';frontClip.style.height=Math.round(MY+104*U)+'px';\n  sheet.style.width=PW*S+'px';\n  paperC.style.width=PW*S+'px';paperC.style.height=PH*S+'px';\n  curl.style.top=(PRINTY-8*U)+'px';curl.style.height=(34*U)+'px';\n  rear.style.width=PW*S+'px';\n  buildScale();\n  paintDesk();sizeMotes();\n  placeProps();\n  update(true);\n}\nfunction paperLeftFor(c){const px=X0+(1-K)*c*CW*S;return px-(ML+c*CW)*S;}\nfunction update(instant){\n  const els=[sheet,rear,carBack,carFront];\n  if(instant)els.forEach(e=>e.classList.add('instant'));\n  const cc=Math.min(col,COLS);\n  const left=paperLeftFor(cc);\n  const mid=SW/2-(PW/2)*S; // paper centred over the machine\n  const shift=left-mid;\n  sheet.style.left='0px';sheet.style.transform='translateX('+left+'px)';\n  rear.style.left=left+'px';\n  const carShift=shift+(SW/2-(MX+MW/2));\n  carBack.style.transform=carFront.style.transform='translateX('+carShift+'px)';\n  const baseY=TM+line*LH;\n  paperC.style.transform='translateY('+(PRINTY-baseY*S)+'px)';\n  const unfed=Math.max(0,PH-baseY-34);\n  rear.style.height=(unfed*S*0.94)+'px';\n  rear.style.top=(MY+62*U-unfed*S*0.94)+'px';\n  // printing point (fixed on desktop, travels a little on phones)\n  const px=X0+(1-K)*cc*CW*S;\n  $('guidePt').setAttribute('transform','translate('+((px-MX)/U).toFixed(1)+' 0)');\n  $('typebar').setAttribute('x2',((px-MX)/U).toFixed(1));\n  if(instant){void sheet.offsetWidth;els.forEach(e=>e.classList.remove('instant'));}\n  status();\n}\nfunction buildScale(){\n  const g=$('scaleTicks');g.innerHTML='';\n  const ns='http://www.w3.org/2000/svg';\n  const rel=S/U;           // paper units → carriage units\n  const mid=500-(PW/2)*rel;\n  for(let c=0;c<=COLS;c++){\n    const x=mid+(ML+c*CW+CW/2)*rel;\n    const t=document.createElementNS(ns,'path');\n    const big=c%5===0;t.setAttribute('d','M'+x.toFixed(1)+' 90v'+(big?4.5:2.6));t.setAttribute('stroke','#3b3634');t.setAttribute('stroke-width',big?1.1:.7);g.appendChild(t);\n    if(big){const tx=document.createElementNS(ns,'text');tx.setAttribute('x',x.toFixed(1));tx.setAttribute('y','99.4');tx.setAttribute('text-anchor','middle');tx.setAttribute('font-size','5.2');tx.setAttribute('font-family','monospace');tx.setAttribute('fill','#2b2725');tx.textContent=c;g.appendChild(tx);}\n  }\n  const bell=mid+(ML+(COLS-6)*CW+CW/2)*rel;\n  const m=document.createElementNS(ns,'path');m.setAttribute('d','M'+bell.toFixed(1)+' 94l2.6 -4.2h-5.2z');m.setAttribute('fill','#b3261e');g.appendChild(m);\n}\n\n/* ---------- the desk: procedural walnut + lamplight ---------- */\nfunction paintDesk(){\n  const dpr=Math.min(2,window.devicePixelRatio||1);\n  deskC.width=Math.round(SW*dpr);deskC.height=Math.round(scene.clientHeight*dpr);\n  const d=deskC.getContext('2d');d.setTransform(dpr,0,0,dpr,0,0);\n  const w=SW,h=scene.clientHeight;const r=mulberry32(21);\n  let y=-20,i=0;\n  const tones=[[92,52,26],[104,60,31],[86,48,24],[98,56,28]];\n  while(y<h){\n    const ph=190+r()*80;const t=tones[i%4];\n    const g=d.createLinearGradient(0,y,0,y+ph);\n    g.addColorStop(0,'rgb('+(t[0]+6)+','+(t[1]+4)+','+(t[2]+2)+')');g.addColorStop(1,'rgb('+(t[0]-8)+','+(t[1]-6)+','+(t[2]-4)+')');\n    d.fillStyle=g;d.fillRect(0,y,w,ph);\n    const n=Math.round(ph/2.4);\n    for(let k=0;k<n;k++){\n      const gy=y+r()*ph,amp=1+r()*5,f=0.0016+r()*0.005,p0=r()*6.28,dark=r()<.62;\n      d.strokeStyle=dark?'rgba(38,18,6,'+(0.08+r()*0.2)+')':'rgba(176,112,60,'+(0.05+r()*0.12)+')';\n      d.lineWidth=0.5+r()*1.7;d.beginPath();\n      for(let x=0;x<=w+12;x+=12){const yy=gy+Math.sin(x*f+p0)*amp+Math.sin(x*f*3.3+p0*2)*amp*0.35;x?d.lineTo(x,yy):d.moveTo(x,yy);}\n      d.stroke();\n    }\n    // a knot now and then\n    if(r()<.55){const kx=r()*w,ky=y+ph*(.3+r()*.4);for(let q=10;q>0;q--){d.strokeStyle='rgba(40,18,6,'+(0.05+q*0.012)+')';d.lineWidth=1;d.beginPath();d.ellipse(kx,ky,q*7,q*2.2,0,0,Math.PI*2);d.stroke();}}\n    d.fillStyle='rgba(18,8,2,.6)';d.fillRect(0,y+ph-2,w,2);\n    d.fillStyle='rgba(255,196,130,.08)';d.fillRect(0,y+ph,w,1);\n    y+=ph;i++;\n  }\n  // lamplight from the upper left + warm bloom behind the machine\n  const L=d.createRadialGradient(w*0.18,-h*0.12,0,w*0.18,-h*0.12,Math.hypot(w,h)*0.95);\n  L.addColorStop(0,'rgba(255,214,150,0.5)');L.addColorStop(.35,'rgba(255,190,120,0.2)');L.addColorStop(.75,'rgba(40,18,6,0.15)');L.addColorStop(1,'rgba(10,4,1,0.62)');\n  d.fillStyle=L;d.fillRect(0,0,w,h);\n  const B=d.createRadialGradient(w/2,h*0.62,0,w/2,h*0.62,Math.max(w,h)*0.5);\n  B.addColorStop(0,'rgba(255,200,130,0.14)');B.addColorStop(1,'rgba(255,200,130,0)');\n  d.fillStyle=B;d.fillRect(0,0,w,h);\n  // coffee ring, long dried\n  if(!mobile){d.strokeStyle='rgba(60,28,8,0.22)';d.lineWidth=3;d.beginPath();d.arc(w*0.9,h*0.3,44,0.3,5.9);d.stroke();d.lineWidth=1;d.strokeStyle='rgba(60,28,8,0.14)';d.beginPath();d.arc(w*0.9+2,h*0.3+1,40,0,6.28);d.stroke();}\n}\nfunction placeProps(){\n  const card=$('card'),tag=$('tag'),pencil=$('pencil');\n  if(mobile){\n    const hb=document.querySelector('header.top').getBoundingClientRect().bottom;\n    card.style.left='18px';card.style.top=(hb+22)+'px';return;\n  }\n  card.style.left=Math.max(24,MX*0.5-140)+'px';card.style.top=(SH*0.44)+'px';\n  pencil.style.left=Math.max(20,MX*0.5-110)+'px';pencil.style.top=(SH*0.44+236)+'px';\n  tag.style.left=(MX+MW+Math.max(18,(SW-MX-MW)*0.5-140))+'px';tag.style.top=(MY+175*U)+'px';\n}\n\n/* ---------- dust motes in the lamp beam ---------- */\nconst M=motesC.getContext('2d');const motes=[];let mdpr=1;\nfunction sizeMotes(){mdpr=Math.min(2,window.devicePixelRatio||1);motesC.width=Math.round(SW*mdpr);motesC.height=Math.round(scene.clientHeight*mdpr);\n  if(!motes.length){const r=mulberry32(9);for(let i=0;i<46;i++)motes.push({x:r(),y:r(),z:.4+r()*.9,p:r()*6.28,s:.3+r()*.7});}}\nfunction drawMotes(t){\n  const w=SW,h=scene.clientHeight;M.setTransform(mdpr,0,0,mdpr,0,0);M.clearRect(0,0,w,h);\n  for(const m of motes){\n    if(!reduced){m.y-=0.00004*m.s*16;m.x+=Math.sin(t*0.0003+m.p)*0.00008;if(m.y<-0.05){m.y=1.05;m.x=Math.random();}}\n    const x=m.x*w,y=m.y*h;\n    const beam=Math.max(0,1-Math.hypot(x/w-0.2,y/h-0.05)*1.35);\n    if(beam<=0)continue;\n    const a=beam*(0.35+0.35*Math.sin(t*0.002+m.p*3));\n    M.fillStyle='rgba(255,226,170,'+a.toFixed(3)+')';M.beginPath();M.arc(x,y,m.z*1.3,0,6.283);M.fill();\n  }\n}\nlet raf=0;function loop(t){raf=requestAnimationFrame(loop);drawMotes(t);}\nfunction startLoop(){if(!raf)raf=requestAnimationFrame(loop);}\nfunction stopLoop(){if(raf){cancelAnimationFrame(raf);raf=0;}}\ndocument.addEventListener('visibilitychange',()=>document.hidden?stopLoop():startLoop());\n\n/* ---------- keyboard (built at runtime from the Marlowe layout) ---------- */\nconst SHIFTED={'1':'!','2':'\"','3':'#','4':'$','5':'%','6':'_','7':'&','8':\"'\",'9':'(','0':')','-':'*',';':':',',':',','.':'.','/':'?'};\nconst ROWS=[\n  {y:150,r:16.5,sp:58,dx:10,keys:['1','2','3','4','5','6','7','8','9','0','-','BS']},\n  {y:190,r:17.5,sp:61,dx:6,keys:['TAB','q','w','e','r','t','y','u','i','o','p']},\n  {y:230,r:18.5,sp:64,dx:3,keys:['LOCK','a','s','d','f','g','h','j','k','l',';']},\n  {y:270,r:19.5,sp:67,dx:0,keys:['SHIFT','z','x','c','v','b','n','m',',','.','/','SHIFT']}\n];\nconst keyEls=new Map();\nfunction buildKeys(){\n  const ns='http://www.w3.org/2000/svg',host=$('keys');\n  const mk=(t,a)=>{const e=document.createElementNS(ns,t);for(const k in a)e.setAttribute(k,a[k]);return e;};\n  ROWS.forEach((row,ri)=>{\n    const n=row.keys.length,x0=500+row.dx-(n-1)*row.sp/2;\n    row.keys.forEach((k,i)=>{\n      const x=x0+i*row.sp,y=row.y,r=row.r,ry=r*0.8;\n      const outer=mk('g',{transform:'translate('+x+' '+y+')'});\n      const g=mk('g',{class:'key','data-k':k,role:'button','aria-label':k==='BS'?'Back space':k==='TAB'?'Tab':k==='LOCK'?'Shift lock':k==='SHIFT'?'Shift':'Key '+k.toUpperCase()});\n      g.appendChild(mk('rect',{x:-2.6,y:0,width:5.2,height:26+ri*2,fill:'#34302d'}));\n      const kc=mk('g',{class:'kc'});\n      kc.appendChild(mk('ellipse',{cx:0,cy:3,rx:r+3.5,ry:ry+3.5,fill:'rgba(20,30,25,.35)'}));\n      kc.appendChild(mk('ellipse',{cx:0,cy:0,rx:r+3,ry:ry+3,fill:'url(#rim)'}));\n      kc.appendChild(mk('ellipse',{cx:0,cy:-.6,rx:r,ry:ry,fill:'url(#cap)',class:'cap'}));\n      const long=k.length>1;\n      const label=k==='BS'?'⌫':(long?k:k.toUpperCase());\n      const tx=mk('text',{x:0,y:long?2.6:r*0.34,'text-anchor':'middle','font-family':MONO,'font-weight':'700','font-size':long?(k==='SHIFT'?6.6:7.4):r*0.95,fill:'#2b2724'});\n      tx.textContent=label;kc.appendChild(tx);\n      if(SHIFTED[k]&&!/[a-z]/.test(k)&&SHIFTED[k]!==k){const st=mk('text',{x:r*0.52,y:-r*0.22,'text-anchor':'middle','font-family':MONO,'font-size':r*0.5,fill:'#8a2a22'});st.textContent=SHIFTED[k];kc.appendChild(st);}\n      g.appendChild(kc);outer.appendChild(g);host.appendChild(outer);\n      if(!keyEls.has(k))keyEls.set(k,[]);keyEls.get(k).push(g);\n    });\n  });\n  keyEls.set(' ',[$('spaceKey')]);\n}\nfunction flashKey(k){\n  const list=keyEls.get(k);if(!list)return;\n  for(const g of list){g.classList.add('down');setTimeout(()=>g.classList.remove('down'),reduced?40:110);}\n}\nfunction keyFor(ch){\n  if(/[a-z]/.test(ch))return ch;\n  if(/[A-Z]/.test(ch))return ch.toLowerCase();\n  if(ch===' ')return ' ';\n  for(const k in SHIFTED){if(SHIFTED[k]===ch)return k;}\n  return keyEls.has(ch)?ch:null;\n}\n\n/* ---------- sound (Web Audio, synthesized) ---------- */\nlet AC=null,master=null,noise=null;\nfunction audio(){\n  if(AC){if(AC.state==='suspended')AC.resume();return;}\n  try{\n    AC=new (window.AudioContext||window.webkitAudioContext)();\n    master=AC.createGain();master.gain.value=muted?0:0.6;master.connect(AC.destination);\n    noise=AC.createBuffer(1,AC.sampleRate*0.6|0,AC.sampleRate);const d=noise.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;\n  }catch(e){AC=null;}\n}\nfunction burst(t,dur,type,freq,q,gain){\n  const s=AC.createBufferSource();s.buffer=noise;const f=AC.createBiquadFilter();f.type=type;f.frequency.value=freq;f.Q.value=q;\n  const g=AC.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+0.002);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);\n  s.connect(f);f.connect(g);g.connect(master);s.start(t,Math.random()*0.5);s.stop(t+dur+0.03);\n}\nfunction thump(t,f0,f1,dur,gain){\n  const o=AC.createOscillator();o.type='triangle';o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(f1,t+dur);\n  const g=AC.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+0.003);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);\n  o.connect(g);g.connect(master);o.start(t);o.stop(t+dur+0.03);\n}\nconst snd={\n  key(){if(!AC||muted)return;const t=AC.currentTime;burst(t,0.035,'bandpass',2100+Math.random()*1500,1.1,0.9);thump(t,210,85,0.05,0.45);burst(t+0.024,0.018,'highpass',5400,0.7,0.22);},\n  space(){if(!AC||muted)return;const t=AC.currentTime;burst(t,0.05,'bandpass',850,0.8,0.45);thump(t,150,60,0.07,0.5);burst(t+0.03,0.02,'highpass',4800,0.7,0.2);},\n  soft(){if(!AC||muted)return;const t=AC.currentTime;burst(t,0.03,'bandpass',1400,1,0.35);},\n  bell(){if(!AC||muted)return;const t=AC.currentTime;\n    [[2093,0.32,1.9],[2093*2.76,0.1,0.8],[2093*5.4,0.05,0.35],[2093*1.5,0.04,0.6]].forEach(([f,gv,d])=>{const o=AC.createOscillator();o.type='sine';o.frequency.value=f;const g=AC.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(gv,t+0.004);g.gain.exponentialRampToValueAtTime(0.0001,t+d);o.connect(g);g.connect(master);o.start(t);o.stop(t+d+0.05);});\n    burst(t,0.02,'highpass',6000,0.7,0.2);},\n  ret(){if(!AC||muted)return;const t=AC.currentTime;\n    for(let i=0;i<6;i++)burst(t+i*0.028,0.016,'highpass',3600,0.8,0.3);\n    const s=AC.createBufferSource();s.buffer=noise;const f=AC.createBiquadFilter();f.type='bandpass';f.Q.value=0.9;f.frequency.setValueAtTime(1400,t+0.1);f.frequency.exponentialRampToValueAtTime(380,t+0.45);\n    const g=AC.createGain();g.gain.setValueAtTime(0.0001,t+0.1);g.gain.exponentialRampToValueAtTime(0.16,t+0.16);g.gain.exponentialRampToValueAtTime(0.0001,t+0.46);\n    s.connect(f);f.connect(g);g.connect(master);s.start(t+0.1);s.stop(t+0.5);\n    thump(t+0.45,130,48,0.1,0.75);burst(t+0.45,0.05,'bandpass',1500,1,0.55);},\n  paper(){if(!AC||muted)return;const t=AC.currentTime;\n    const s=AC.createBufferSource();s.buffer=noise;s.loop=true;const f=AC.createBiquadFilter();f.type='bandpass';f.Q.value=0.6;f.frequency.setValueAtTime(900,t);f.frequency.exponentialRampToValueAtTime(3800,t+0.55);\n    const g=AC.createGain();g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(0.28,t+0.08);g.gain.exponentialRampToValueAtTime(0.0001,t+0.7);\n    s.connect(f);f.connect(g);g.connect(master);s.start(t);s.stop(t+0.75);\n    for(let i=0;i<9;i++)burst(t+0.05+i*0.05,0.012,'highpass',4200,0.8,0.12);}\n};\n\n/* ---------- typing ---------- */\nlet seedCounter=1;\nfunction strike(){\n  const tb=$('typebar'),sp=$('spark');\n  tb.classList.remove('strike');sp.classList.remove('strike');void tb.getBBox;\n  requestAnimationFrame(()=>{tb.classList.add('strike');sp.classList.add('strike');});\n}\nfunction typeChar(ch){\n  audio();\n  if(line>=LINES){toast('The sheet is full — press <b>New sheet</b> for a fresh page');snd.soft();return;}\n  const c=Math.min(col,COLS);\n  const s=[ch,c,line,red?1:0,(Date.now()+seedCounter++*7919)%2147483647];\n  strokes.push(s);stampOne(s);\n  flashKey(keyFor(ch));strike();snd.key();\n  if(col<COLS)col++;\n  else toast('Margin locked — pull the lever or press <b>Return</b>');\n  checkBell();update(false);persist();\n  if(shiftOn&&!lockOn){shiftOn=false;syncShift();}\n}\nfunction space(){audio();flashKey(' ');snd.space();if(col<COLS)col++;checkBell();update(false);persist();}\nfunction backspace(){audio();flashKey('BS');snd.soft();if(col>0)col--;update(false);persist();}\nfunction tab(){audio();flashKey('TAB');snd.space();col=Math.min(COLS,(Math.floor(col/5)+1)*5);checkBell();update(false);persist();}\nfunction carriageReturn(){\n  audio();\n  const lv=$('lever');lv.classList.remove('pull');void lv.getBBox;requestAnimationFrame(()=>lv.classList.add('pull'));\n  snd.ret();\n  [sheet,rear,carBack,carFront].forEach(e=>e.classList.add('returning'));\n  setTimeout(()=>[sheet,rear,carBack,carFront].forEach(e=>e.classList.remove('returning')),520);\n  col=0;bellRung=false;\n  if(line<LINES)line++;\n  if(line>=LINES)toast('Last line reached — the sheet is full');\n  update(false);persist();\n  announce('New line, line '+(line+1));\n}\nfunction checkBell(){\n  if(!bellRung&&col>=COLS-6){bellRung=true;snd.bell();ding();}\n}\nfunction ding(){\n  const d=document.createElement('div');d.className='ding';d.textContent='ding';\n  const px=X0+(1-K)*Math.min(col,COLS)*CW*S;\n  d.style.left=(px+40*U)+'px';d.style.top=(MY+20*U)+'px';scene.appendChild(d);setTimeout(()=>d.remove(),1400);\n}\n\n/* ---------- ribbon ---------- */\nfunction setRibbon(isRed){\n  red=isRed;$('inkBlack').setAttribute('aria-pressed',String(!red));$('inkRed').setAttribute('aria-pressed',String(red));\n  $('vibrator').setAttribute('transform',red?'translate(0 -3.8)':'translate(0 0)');\n  audio();snd.soft();persist();\n}\n$('inkBlack').addEventListener('click',()=>setRibbon(false));\n$('inkRed').addEventListener('click',()=>setRibbon(true));\n\n/* ---------- shift ---------- */\nfunction syncShift(){\n  (keyEls.get('SHIFT')||[]).forEach(g=>g.classList.toggle('on',shiftOn&&!lockOn));\n  (keyEls.get('LOCK')||[]).forEach(g=>g.classList.toggle('on',lockOn));\n}\nfunction onScreenKey(k){\n  if(k==='BS'){backspace();return;}\n  if(k==='TAB'){tab();return;}\n  if(k==='SHIFT'){shiftOn=!shiftOn;audio();snd.soft();flashKey('SHIFT');syncShift();return;}\n  if(k==='LOCK'){lockOn=!lockOn;shiftOn=lockOn;audio();snd.soft();syncShift();return;}\n  if(k===' '){space();return;}\n  const up=shiftOn||lockOn;\n  let ch=k;\n  if(/[a-z]/.test(k))ch=up?k.toUpperCase():k;\n  else if(up&&SHIFTED[k])ch=SHIFTED[k];\n  typeChar(ch);\n}\n\n/* ---------- input: physical keyboard, on-screen keys, phone keyboard ---------- */\nconst ghost=$('ghost');\nwindow.addEventListener('keydown',e=>{\n  if(e.ctrlKey||e.metaKey||e.altKey)return;\n  const tgt=e.target,tag=tgt&&tgt.tagName;\n  const onButton=tag==='BUTTON'||(tgt&&tgt.getAttribute&&tgt.getAttribute('role')==='button');\n  if(e.key==='Enter'){\n    if(onButton&&tgt.id!=='lever')return;\n    e.preventDefault();carriageReturn();return;\n  }\n  if(e.key==='Backspace'){e.preventDefault();backspace();return;}\n  if(e.key==='Tab'&&tgt===ghost){e.preventDefault();tab();return;}\n  if(e.key==='Unidentified'||e.isComposing)return;\n  if(e.key.length===1){\n    if(onButton&&e.key===' ')return;\n    e.preventDefault();\n    if(e.key===' ')space();else typeChar(e.key);\n  }\n});\nghost.addEventListener('input',()=>{\n  const v=ghost.value;ghost.value='';\n  for(const ch of v){if(ch==='\\n')carriageReturn();else if(ch===' ')space();else typeChar(ch);}\n});\nfunction focusGhost(){try{ghost.focus({preventScroll:true});}catch(e){ghost.focus();}}\nsheet.addEventListener('pointerdown',e=>{audio();if(e.pointerType!=='mouse')focusGhost();});\n$('btnKeyboard').addEventListener('click',()=>{audio();focusGhost();toast('Your phone keyboard now types onto the sheet');});\nbodyS.addEventListener('pointerdown',e=>{\n  const g=e.target.closest&&e.target.closest('.key');if(!g)return;\n  e.preventDefault();onScreenKey(g.getAttribute('data-k'));\n});\nconst lever=$('lever');\nlever.addEventListener('pointerdown',e=>{e.preventDefault();carriageReturn();});\nlever.addEventListener('keydown',e=>{if(e.key===' '){e.preventDefault();carriageReturn();}});\n\n/* ---------- controls ---------- */\nconst btnSound=$('btnSound');\nbtnSound.addEventListener('click',()=>{\n  muted=!muted;audio();if(master)master.gain.value=muted?0:0.6;\n  btnSound.setAttribute('aria-pressed',String(!muted));btnSound.setAttribute('aria-label',muted?'Sound muted — press to unmute':'Sound on — press to mute');\n  $('sndLbl').textContent=muted?'Muted':'Sound';$('sndWaves').style.opacity=muted?0.15:1;\n  try{localStorage.setItem('marlowe44.muted',muted?'1':'0');}catch(e){}\n});\n$('btnNew').addEventListener('click',newSheet);\n// a mouse click should not leave focus on a control, or the next space bar would press it again\ndocument.querySelectorAll('.controls button').forEach(b=>b.addEventListener('click',e=>{if(e.detail>0)b.blur();}));\nlet busy=false;\nfunction newSheet(){\n  if(busy)return;busy=true;audio();snd.paper();\n  sheet.classList.add('pulling');rear.classList.add('pulling');\n  setTimeout(()=>{\n    sheetNo++;strokes=[];col=0;line=0;bellRung=false;\n    redrawAll();\n    sheet.classList.remove('pulling');rear.classList.remove('pulling');\n    update(true);\n    sheet.classList.add('feeding');rear.classList.add('feeding');\n    setTimeout(()=>{sheet.classList.remove('feeding');rear.classList.remove('feeding');busy=false;},720);\n    persist();toast('Sheet No. '+sheetNo+' is in the machine');\n  },reduced?60:760);\n}\n$('btnSave').addEventListener('click',()=>{\n  try{\n    paperC.toBlob(b=>{\n      if(!b){toast('This browser would not hand over the page');return;}\n      const u=makeObj.call(URL,b),a=document.createElement('a');a.href=u;a.download='marlowe44-letter-sheet'+sheetNo+'.png';\n      document.body.appendChild(a);a.click();a.remove();setTimeout(()=>dropObj.call(URL,u),5000);\n      toast('Letter saved as a PNG — <b>ready to post</b>');\n    },'image/png');\n  }catch(e){toast('This browser would not hand over the page');}\n});\nconst makeObj=URL.createObjectURL,dropObj=URL.revokeObjectURL;\n\n/* ---------- status, toast, persistence ---------- */\nlet toastT=0;\nfunction toast(html){const t=$('toast');t.innerHTML=html;t.classList.add('show');clearTimeout(toastT);toastT=setTimeout(()=>t.classList.remove('show'),2600);}\nfunction announce(s){$('announce').textContent=s;}\nfunction status(){\n  $('stSheet').textContent='No. '+sheetNo;\n  $('stLine').textContent=Math.min(line+1,LINES)+' / '+LINES;\n  $('stCol').textContent=Math.min(col+1,COLS+1)+' / '+COLS;\n  $('stCount').textContent=strokes.length;\n}\nlet saveT=0;\nfunction persist(){clearTimeout(saveT);saveT=setTimeout(()=>{try{localStorage.setItem(STORE,JSON.stringify({strokes:strokes.slice(-3000),col,line,red,sheetNo,bellRung}));}catch(e){}},350);}\nfunction restore(){\n  try{\n    const raw=localStorage.getItem(STORE);if(!raw)return false;\n    const d=JSON.parse(raw);if(!d||!Array.isArray(d.strokes))return false;\n    strokes=d.strokes.filter(s=>Array.isArray(s)&&s.length===5);col=d.col|0;line=d.line|0;red=!!d.red;sheetNo=d.sheetNo|0||1;bellRung=!!d.bellRung;\n    return true;\n  }catch(e){return false;}\n}\nfunction openingLines(){\n  // the machine arrives with the date and a salutation already on the sheet\n  const now=new Date();\n  const months=['January','February','March','April','May','June','July','August','September','October','November','December'];\n  const date=now.getDate()+' '+months[now.getMonth()]+' '+now.getFullYear();\n  let seed=424242;\n  const put=(txt,c0,l)=>{for(let i=0;i<txt.length;i++){if(txt[i]!==' ')strokes.push([txt[i],c0+i,l,0,seed+=7919]);}};\n  put(date,COLS-date.length,0);\n  put('Dear friend,',0,2);\n  put('Forgive the smudges; the Marlowe and I are',5,4);\n  put('still getting acquainted.',0,5);\n  col=26;line=5;\n}\n\n/* ---------- boot ---------- */\nbuildKeys();\ntry{muted=localStorage.getItem('marlowe44.muted')==='1';}catch(e){}\nif(muted){btnSound.setAttribute('aria-pressed','false');$('sndLbl').textContent='Muted';$('sndWaves').style.opacity=0.15;btnSound.setAttribute('aria-label','Sound muted — press to unmute');}\nif(!restore())openingLines();\n$('inkBlack').setAttribute('aria-pressed',String(!red));$('inkRed').setAttribute('aria-pressed',String(red));\n$('vibrator').setAttribute('transform',red?'translate(0 -3.8)':'translate(0 0)');\nredrawAll();\nlayout();\nstartLoop();\nlet rz=0;\nwindow.addEventListener('resize',()=>{clearTimeout(rz);rz=setTimeout(layout,80);});\nif(window.visualViewport)window.visualViewport.addEventListener('resize',()=>{clearTimeout(rz);rz=setTimeout(layout,80);});\nreduceMQ.addEventListener&&reduceMQ.addEventListener('change',e=>{reduced=e.matches;});\n})();\n</script>\n</body>\n</html>\n";
